/// <summary>
/// Base class for PricingAttribute table <c>InventTableModule</c> for sales.
/// </summary>
internal abstract class GUPPricingAttributeInventTableModuleSales extends GUPPricingAttributeInventTableModule implements GUPIPricingAttribute
{

}

Method.Source:
protected InventTableModule getTableRecord(Common _pricingObject)
{
    SalesLine                       salesLine;
    SalesQuotationLine              salesQoutationLine;
    InventTableModule               inventTableModule;

    Switch (_pricingObject.tableId)
    {

        case tableNum(SalesLine):
            salesLine = _pricingObject as SalesLine;
            if (salesLine)
            {
                inventTableModule = salesLine.inventTable().inventTableModuleSales();
            }
            break;

        case tableNum(SalesQuotationLine):
            salesQoutationLine = _pricingObject as SalesQuotationLine;
            if (salesQoutationLine)
            {
                inventTableModule = salesQoutationLine.inventTable().inventTableModuleSales();
            }
            break;
    }

    return inventTableModule;
}

public str getQueryBuilderDatasourceIdentifier()
{
    return strFmt("%1 - %2", enum2Str(ModuleInventPurchSales::Sales), tableStr(InventTableModule));
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbds, qbdsRoot;
    QueryBuildDataSource qbdsExistsJoin;

    if (_qbdsMap && _qbdsMap.exists(tableStr(InventTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(InventTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(InventTable));
        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(InventTable), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
    {
        qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
    }
    else
    {
        qbds = qbdsRoot.addDataSource(tableNum(InventTableModule));
        qbds.addLink(fieldNum(InventTable, ItemId), fieldNum(InventTableModule, ItemId));
        qbds.joinMode(JoinMode::InnerJoin);

        QueryBuildRange qbRange = qbds.addRange(fieldNum(InventTableModule, ModuleType));
        qbRange.value(enum2Str(ModuleInventPurchSales::Sales));

        if (_qbdsMap)
        {
            _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
        }
    }

    return qbds;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}

public GUPPricingAttributeTableFieldPath getPath()
{
    return strFmt('%1#%2_%3$%4#%5_%6$%7#%8',
        tableStr(SalesLine),
        tableStr(InventTable),
        fieldStr(SalesLine, ItemId),
        fieldStr(InventTable, ItemId),
        tableStr(InventTableModule),
        fieldStr(InventTable, ItemId),
        fieldStr(InventTableModule, ItemId),
        this.getAttributeFieldIdentifier());
}
